238  void XFileImporter::CreateMeshes( aiScene* pScene, aiNode* pNode, const std::vector<XFile::Mesh*>& pMeshes) {
   239      if (pMeshes.empty()) {
   240          return;
   241      }
   242
   243      // create a mesh for each mesh-material combination in the source node
   244      std::vector<aiMesh*> meshes;
   245      for( unsigned int a = 0; a < pMeshes.size(); ++a ) {
   246          XFile::Mesh* sourceMesh = pMeshes[a];
   247          if ( nullptr == sourceMesh ) {
   248              continue;
   249          }
   250
   251          // first convert its materials so that we can find them with their index afterwards
   252          ConvertMaterials( pScene, sourceMesh->mMaterials);
   253
   254          unsigned int numMaterials = std::max( (unsigned int)sourceMesh->mMaterials.size(), 1u);
   255          for( unsigned int b = 0; b < numMaterials; ++b ) {
   256              // collect the faces belonging to this material
   257              std::vector<unsigned int> faces;
   258              unsigned int numVertices = 0;
   259              if( !sourceMesh->mFaceMaterials.empty() ) {
   260                  // if there is a per-face material defined, select the faces with the corresponding material
   261                  for( unsigned int c = 0; c < sourceMesh->mFaceMaterials.size(); ++c ) {
   262                      if( sourceMesh->mFaceMaterials[c] == b) {
   263                          faces.push_back( c);
   264                          numVertices += (unsigned int)sourceMesh->mPosFaces[c].mIndices.size();
   265                      }
   266                  }
   267              } else {
   268                  // if there is no per-face material, place everything into one mesh
   269                  for( unsigned int c = 0; c < sourceMesh->mPosFaces.size(); ++c ) {
   270                      faces.push_back( c);
   271                      numVertices += (unsigned int)sourceMesh->mPosFaces[c].mIndices.size();
   272                  }
   273              }
   274
   275              // no faces/vertices using this material? strange...
   276              if ( numVertices == 0 ) {
   277                  continue;
   278              }
   279
   280              // create a submesh using this material
   281              aiMesh* mesh = new aiMesh;
   282              meshes.push_back( mesh);
   283
   284              // find the material in the scene's material list. Either own material
   285              // or referenced material, it should already have a valid index
   286              if( !sourceMesh->mFaceMaterials.empty() ) {
   287                  mesh->mMaterialIndex = static_cast<unsigned int>(sourceMesh->mMaterials[b].sceneIndex);
   288              } else {
   289                  mesh->mMaterialIndex = 0;
   290              }
   291
   292              // Create properly sized data arrays in the mesh. We store unique vertices per face,
   293              // as specified
   294              mesh->mNumVertices = numVertices;
   295              mesh->mVertices = new aiVector3D[numVertices];
   296              mesh->mNumFaces = (unsigned int)faces.size();
   297              mesh->mFaces = new aiFace[mesh->mNumFaces];
   298
   299              // name
   300              mesh->mName.Set(sourceMesh->mName);
   301
   302              // normals?
   303              if ( sourceMesh->mNormals.size() > 0 ) {
   304                  mesh->mNormals = new aiVector3D[ numVertices ];
   305              }
   306              // texture coords
   307              for( unsigned int c = 0; c < AI_MAX_NUMBER_OF_TEXTURECOORDS; ++c ) {
   308                  if ( !sourceMesh->mTexCoords[ c ].empty() ) {
   309                      mesh->mTextureCoords[ c ] = new aiVector3D[ numVertices ];
   310                  }
   311              }
   312              // vertex colors
   313              for( unsigned int c = 0; c < AI_MAX_NUMBER_OF_COLOR_SETS; ++c ) {
   314                  if ( !sourceMesh->mColors[ c ].empty() ) {
   315                      mesh->mColors[ c ] = new aiColor4D[ numVertices ];
   316                  }
   317              }
   318
   319              // now collect the vertex data of all data streams present in the imported mesh
   320              unsigned int newIndex( 0 );
   321              std::vector<unsigned int> orgPoints; // from which original point each new vertex stems
   322              orgPoints.resize( numVertices, 0);
   323
